<?php
class KasirController{
function index(){require_login();$db=Database::connect();$produk=$db->query('SELECT * FROM produk WHERE stok>0 ORDER BY nama')->fetchAll();$pelanggan=$db->query('SELECT * FROM pelanggan ORDER BY nama')->fetchAll();require __DIR__.'/../views/kasir/index.php';}
function customerStore(){require_login();$nama=trim($_POST['nama']??'');if($nama==='')flash('error','Nama pelanggan wajib diisi.');else{$s=Database::connect()->prepare('INSERT INTO pelanggan(nama,telepon,alamat) VALUES(?,?,?)');$s->execute([$nama,trim($_POST['telepon']??''),trim($_POST['alamat']??'')]);flash('success','Pelanggan berhasil didaftarkan.');}redirect('?page=kasir');}
function checkout(){require_login();$items=json_decode($_POST['items']??'[]',true);if(!is_array($items)||!count($items)){flash('error','Keranjang masih kosong.');redirect('?page=kasir');}$db=Database::connect();$member=null;$phone=trim($_POST['member_phone']??'');$method=in_array($_POST['payment_method']??'', ['cash','qris','transfer'],true)?$_POST['payment_method']:'cash';$cashReceived=$method==='cash'?(float)($_POST['cash_received']??0):0;if($phone){$s=$db->prepare('SELECT id FROM pelanggan WHERE telepon=?');$s->execute([$phone]);$member=$s->fetchColumn();if(!$member){flash('error','Nomor HP member tidak ditemukan.');redirect('?page=kasir');}}$db->beginTransaction();$total=0;$valid=[];foreach($items as $i){$s=$db->prepare('SELECT stok,harga,nama FROM produk WHERE id=? FOR UPDATE');$s->execute([$i['id']]);$p=$s->fetch();$q=(int)$i['qty'];if(!$p||$q<1||$q>$p['stok']){$db->rollBack();flash('error','Stok produk tidak mencukupi.');redirect('?page=kasir');}$sub=$q*$p['harga'];$total+=$sub;$valid[]=[$i['id'],$q,$p['harga'],$sub];}$change=$method==='cash'?$cashReceived-$total:0;if($method==='cash'&&$cashReceived<$total){$db->rollBack();flash('error','Uang diterima kurang dari total belanja.');redirect('?page=kasir');}foreach($valid as $x)$db->prepare('UPDATE produk SET stok=stok-? WHERE id=?')->execute([$x[1],$x[0]]);$db->prepare('INSERT INTO transaksi(user_id,pelanggan_id,payment_method,total,cash_received,change_amount) VALUES(?,?,?,?,?,?)')->execute([auth()['id'],$member,$method,$total,$cashReceived,$change]);$id=$db->lastInsertId();$d=$db->prepare('INSERT INTO detail_transaksi(transaksi_id,produk_id,jumlah,harga,subtotal) VALUES(?,?,?,?,?)');foreach($valid as $x)$d->execute([$id,...$x]);$db->commit();redirect('?page=kasir/receipt&id='.$id);}
function receipt(){require_login();$db=Database::connect();$s=$db->prepare('SELECT t.*,u.nama kasir,p.nama pelanggan,p.telepon FROM transaksi t JOIN users u ON u.id=t.user_id LEFT JOIN pelanggan p ON p.id=t.pelanggan_id WHERE t.id=?');$s->execute([$_GET['id']]);$transaction=$s->fetch();$s=$db->prepare('SELECT d.*,p.nama FROM detail_transaksi d JOIN produk p ON p.id=d.produk_id WHERE d.transaksi_id=?');$s->execute([$_GET['id']]);$items=$s->fetchAll();require __DIR__.'/../views/kasir/receipt.php';}}
